using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Web.Script.Serialization;

internal static class RiftVerification {
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static DateTimeOffset U(string text){return DateTimeOffset.Parse(text,System.Globalization.CultureInfo.InvariantCulture);}
    static void ServiceCycle(EnergyOverlay owner,string root){var notices=new List<RiftAlertLedger.Notice>();bool game=true;var options=new NotificationOptions{Sound=false};var json=new JavaScriptSerializer();using(var overlay=new NotificationOverlay(owner,root,new NotificationSignal(),true))using(var service=new RiftService(owner,overlay,root,true,()=>game,n=>notices.Add(n))){service.Configure(options,true);var profile=EnemyTargetVerification.Player(123,"Test",10000,12000,true);service.Identity.Consume(profile,0,profile.Length,1,"own");service.Maintain(U("2026-10-20T17:54:59Z"));Check(notices.Count==0&&service.Region=="eu","Actual controller identifies server before its schedule");service.Maintain(U("2026-10-20T17:55:00Z"));Check(notices.Count==1&&!notices[0].Opening&&!notices[0].Closing,"Controller emits advance notice");service.Maintain(U("2026-10-20T18:00:00Z"));Check(notices.Count==2&&notices[1].Opening,"Controller emits20:00 EU opening");service.Maintain(U("2026-10-20T18:04:00Z"));Check(json.Serialize(service.Status).Contains("06:00"),"Controller countdown follows the fixed closing deadline");service.Maintain(U("2026-10-20T18:10:00Z"));Check(notices.Count==3&&notices[2].Closing,"Controller emits closing through the shared notification callback");Check(json.Serialize(service.Status).Contains("\"remaining\":null"),"Controller clears the expired entry countdown");service.Maintain(U("2026-10-20T18:10:10Z"));Check(notices.Count==3,"Controller does not repeat closure");service.Maintain(U("2026-10-20T17:59:00Z"));service.Maintain(U("2026-10-20T18:00:00Z"));Check(notices.Count==3,"Clock moving backwards does not replay claimed alerts");game=false;service.Maintain(U("2026-10-20T20:55:00Z"));Check(notices.Count==3,"Controller is silent while game closed");}}
    internal static void Run(string root){
        var before=U("2026-10-20T17:54:59Z");var opening=U("2026-10-20T18:00:00Z");var options=new RiftOptions();var ledger=new RiftAlertLedger();
        Check(ledger.Poll(before,"eu",options,true)==null,"No early Rift reminder");var n=ledger.Poll(before.AddSeconds(1),"eu",options,true);Check(n!=null&&!n.Opening&&n.Minutes==5,"Five-minute EU reminder");Check(ledger.Poll(before.AddSeconds(2),"eu",options,true)==null,"Reminder delivered once");
        n=ledger.Poll(opening,"eu",options,true);Check(n!=null&&n.Opening,"EU20:00 opening is18:00UTC in October summer time");Check(ledger.Poll(opening.AddSeconds(1),"eu",options,true)==null,"Opening delivered once independently");Check(new RiftAlertLedger().Poll(opening,null,options,true)==null,"Unknown region cannot guess opening");Check(new RiftAlertLedger().Poll(opening,"eu",options,false)==null,"Disabled/game-closed schedule is silent");Check(new RiftAlertLedger().Poll(opening.AddMinutes(2),"eu",options,true)==null,"Do not replay an old opening alert at startup");
        n=ledger.Poll(opening.AddMinutes(10),"eu",options,true);Check(n!=null&&n.Closing&&!n.Opening,"Closing is a normal notification at the entry deadline");Check(ledger.Poll(opening.AddMinutes(10).AddSeconds(1),"eu",options,true)==null,"Closing delivered once");var closeOff=options.Copy();closeOff.Closing=false;Check(new RiftAlertLedger().Poll(opening.AddMinutes(10),"eu",closeOff,true)==null,"Closing can be disabled independently");
        string ledgerFile=Path.Combine(root,"rift-test-ledger.json");var persistent=new RiftAlertLedger(ledgerFile);Check(persistent.Poll(opening,"eu",options,true)!=null&&new RiftAlertLedger(ledgerFile).Poll(opening.AddSeconds(1),"eu",options,true)==null,"Delivered openings survive Helper restart without repeats");
        var active=RiftCalendar.Active(opening.AddMinutes(4),"eu");Check(active!=null&&RiftCalendar.Remaining(active.Closing,opening.AddMinutes(4))=="06:00","Startup during entry window uses the real deadline");Check(RiftCalendar.Active(opening.AddMinutes(10),"eu")==null,"Portal countdown ends exactly after ten minutes");Check(RiftCalendar.Next(opening,"eu")==opening.AddHours(3),"Next opening is the next scheduled slot");
        Check(RiftCalendar.Active(U("2026-12-01T19:00:00Z"),"eu")!=null,"Winter20:00 Europe is19:00UTC");var zone=RiftCalendar.Zone("eu");Check(!RiftCalendar.Openings(U("2026-03-29T00:00:00Z"),zone).Any(t=>TimeZoneInfo.ConvertTime(t,zone).Date==new DateTime(2026,3,29)&&TimeZoneInfo.ConvertTime(t,zone).Hour==2),"Nonexistent daylight-saving wall hour is skipped");Check(RiftCalendar.Openings(U("2026-10-25T00:00:00Z"),zone).Count(t=>TimeZoneInfo.ConvertTime(t,zone).Date==new DateTime(2026,10,25)&&TimeZoneInfo.ConvertTime(t,zone).Hour==2)==2,"Ambiguous wall-clock instants remain distinct");
        foreach(int id in new[]{1301,2301,1332,2350})Check(RiftCalendar.RegionForServer(id)=="eu","EU server encoding");foreach(int id in new[]{0,1001,2001,1351,9999})Check(RiftCalendar.RegionForServer(id)==null,"Unknown server encoding stays unknown");Check(RiftCalendar.RegionForServer(2101)=="nae"&&RiftCalendar.RegionForServer(2201)=="naw"&&RiftCalendar.RegionForServer(2401)=="sa"&&RiftCalendar.RegionForServer(2501)=="asia","Other Global regions");
        var identity=new RiftIdentity();identity.Configure(true);byte[] profile=EnemyTargetVerification.Player(123,"Test",10000,12000,true);identity.Consume(profile,0,profile.Length,1,"one");Check(identity.Server==1301,"Region uses actual own-profile server field");var other=EnemyTargetVerification.Player(124,"Remote",10000,12000,false);identity.Consume(other,0,other.Length,2,"two");Check(identity.Server==1301,"Party profiles cannot change own server");identity.Reset();Check(identity.Server==0,"Transport reset clears server identity");identity.Configure(false);identity.Consume(profile,0,profile.Length,3,"one");Check(identity.Server==0,"Disabled identity reader ignores input");
        var source=new NotificationOptions();source.Rift.Counter.Color="#123456";var copy=source.Copy();copy.Rift.Counter.Color="#FFFFFF";copy.Rift.Region="eu";Check(source.Rift.Region=="auto"&&source.Rift.Counter.Color=="#123456","Rift configuration is a deep independent copy");var json=new JavaScriptSerializer();var restored=NotificationOptions.Read(json.Deserialize<Dictionary<string,object>>(json.Serialize(new{notifications=source})));Check(NotificationOptions.Same(restored,source),"Rift preferences round trip with existing notification preferences");source.Enabled=false;Check(source.NeedsCapture,"Independent automatic countdown can retain capture demand with notifications off");source.Rift.Counter.Enabled=false;Check(!source.NeedsCapture,"All disabled Rift/invitation capture demand stops");
        var counter=new RiftCounterOptions();var center=new Point(counter.ActualBounds.X+counter.ActualBounds.Width/2,counter.ActualBounds.Y+counter.ActualBounds.Height/2);foreach(int scale in new[]{50,100,150,300}){counter.ScalePercent=scale;var b=counter.ActualBounds;Check(Math.Abs(b.X+b.Width/2-center.X)<=1&&Math.Abs(b.Y+b.Height/2-center.Y)<=1,"Whole-counter scale grows symmetrically around center");}
        using(var stream=typeof(RiftVerification).Assembly.GetManifestResourceStream("Notification.rift.png"))using(var icon=new Bitmap(stream)){Check(icon.GetPixel(0,0).A==0&&icon.GetPixel(icon.Width/2,icon.Height/2).A==0,"Rift icon background and hollow center remain truly transparent");}
        string designs=Path.Combine(root,"designs");Directory.CreateDirectory(designs);using(var paint=new RiftCounterPaint())using(var workspace=new FpsDesign.Workspace())foreach(string language in new[]{"es","en"}){
            var o=new NotificationOptions();using(var alert=NotificationDesign.RenderFitted(540,240,null,language,o,false,workspace,false,true,false,true,5))using(var clock=paint.Render(new RiftCounterOptions(),language,"09:59",false)){
                alert.Save(Path.Combine(designs,"rift-opening-"+language+".png"));clock.Save(Path.Combine(designs,"rift-counter-"+language+".png"));using(var closing=NotificationDesign.RenderFitted(540,240,null,language,o,false,workspace,false,false,false,true,5,true))closing.Save(Path.Combine(designs,"rift-closing-"+language+".png"));Check(alert.GetPixel(0,0).A==0&&clock.GetPixel(clock.Width-1,0).A==0,"Rift art and gradient have transparent corners");
                using(var sheet=new Bitmap(660,330))using(var g=Graphics.FromImage(sheet))using(var font=new Font("Segoe UI",11,FontStyle.Regular,GraphicsUnit.Pixel))using(var brush=new SolidBrush(Color.FromArgb(150,158,172))){g.Clear(Color.FromArgb(24,29,36));g.DrawString(language=="es"?"NOTIFICACIÓN":"NOTIFICATION",font,brush,38,20);g.DrawImageUnscaled(alert,(660-alert.Width)/2,49);g.DrawString(language=="es"?"CONTADOR INDEPENDIENTE":"INDEPENDENT COUNTDOWN",font,brush,38,191);g.DrawImageUnscaled(clock,(660-clock.Width)/2,220);sheet.Save(Path.Combine(designs,"rift-design-"+language+".png"));}
            }
        }
        using(var owner=new EnergyOverlay(root,true)){ServiceCycle(owner,root);using(var notice=new NotificationOverlay(owner,root,new NotificationSignal(),true))notice.VerifyRiftNative();using(var nativeCounter=new RiftCounterOverlay(owner,true))nativeCounter.VerifyNative();var settings=new HelperSettings(owner);try{var cfg=owner.Configuration;cfg.Language="es";owner.ApplyConfiguration(cfg);settings.ShowRift();settings.VerifyRift(root);}finally{settings.Close();}}
        File.WriteAllText(Path.Combine(root,"rift-test.txt"),"PASS: regional UTC/DST schedules; unknown-region suppression; separate warning/opening deduplication; ten-minute fixed deadline and mid-window startup; validated own identity; independent counter capture demand; deep preferences/undo; centered whole scale; transparent embedded icon and EN/ES designs; native notification queue and category isolation; cached previews. Scheduled availability, not live portal confirmation.");
    }
}
